import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import type { UserProfile } from "@unomed/react-native-matrix-sdk";
import { format, isToday } from "date-fns";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { useEffect, useState } from "react";
import { AppBottomSheet } from "shared/components/bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { UserProfileImage } from "../user-profile-image";

interface RowProps {
  userId: string;
  timestamp: number | null;
}

const SeenByRow: React.FC<RowProps> = ({ userId, timestamp }) => {
  const [profile, setProfile] = useState<UserProfile | null>(null);
  const displayName =
    profile?.displayName ?? userId.replace("@", "").split(":")[0];

  useEffect(() => {
    MatrixCore.getClient().getProfile(userId).then(setProfile).catch();
  }, [userId]);

  return (
    <Block
      flexDirection="row"
      align="center"
      gap={12}
      paddings={{ paddingVertical: 12 }}
      border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
    >
      <UserProfileImage user={profile} width={36} height={36} />
      <Block flex={1} gap={2}>
        <Text color={Colors.white} font="InstrumentSans-Bold">
          {displayName}
        </Text>
        <Text
          size={TextSize.small}
          color={Colors.white50}
          font="InstrumentSans-Regular"
        >
          {userId}
        </Text>
      </Block>
      {!!timestamp && (
        <Text
          size={TextSize.small}
          color={Colors.white50}
          font="InstrumentSans-Regular"
        >
          {isToday(timestamp)
            ? format(timestamp, "HH:mm")
            : format(timestamp, "MMM d, HH:mm")}
        </Text>
      )}
    </Block>
  );
};

interface Props {
  isOpen: boolean;
  users: TimelineSeenByUser[];
  onClose: () => void;
}

export const SeenByBottomSheet: React.FC<Props> = ({
  isOpen,
  users,
  onClose,
}) => {
  return (
    <AppBottomSheet
      isOpen={isOpen}
      onClose={onClose}
      enableContentPanningGesture={false}
    >
      <BottomSheetScrollView stickyHeaderIndices={[0]}>
        <Block
          paddings={{ paddingHorizontal: 20, paddingTop: 4, paddingBottom: 8 }}
          background={Colors.blackMinus1}
        >
          <Text
            font="InstrumentSans-Bold"
            color={Colors.white}
            size={TextSize.medium}
            margins={{ marginBottom: 16 }}
          >
            Seen by
          </Text>
        </Block>
        <Block paddings={{ paddingHorizontal: 20, paddingBottom: 56 }}>
          {users.map(({ userId, timestamp }) => (
            <SeenByRow key={userId} userId={userId} timestamp={timestamp} />
          ))}
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import { useEffect, useState } from "react";
import { ScrollView } from "react-native";
import { AppBottomSheet } from "shared/components/bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { ReactionUserRow } from "./fragments";

interface Props {
  isOpen: boolean;
  reactions: TimelineReaction[];
  onClose: () => void;
}

export const ReactionsBottomSheet: React.FC<Props> = ({
  isOpen,
  reactions,
  onClose,
}) => {
  const [activeKey, setActiveKey] = useState<string>("");

  useEffect(() => {
    if (!reactions.length) return;
    setActiveKey(reactions[0].key);
  }, [reactions]);

  const activeReaction =
    reactions.find((r) => r.key === activeKey) ?? reactions[0];

  return (
    <AppBottomSheet
      isOpen={isOpen}
      onClose={onClose}
      enableContentPanningGesture={false}
    >
      <BottomSheetScrollView stickyHeaderIndices={[0]}>
        <Block
          paddings={{ paddingHorizontal: 20, paddingTop: 4, paddingBottom: 8 }}
          background={Colors.blackMinus1}
        >
          <ScrollView
            horizontal
            showsHorizontalScrollIndicator={false}
            contentContainerStyle={{ gap: 8 }}
          >
            {reactions.map((reaction) => {
              const isActive = reaction.key === activeKey;
              return (
                <Block
                  key={reaction.key}
                  onTouchEnd={() => setActiveKey(reaction.key)}
                  background={isActive ? Colors.primary : Colors.white10}
                  border={{ borderRadius: 20 }}
                  paddings={{ paddingHorizontal: 12, paddingVertical: 6 }}
                  flexDirection="row"
                  align="center"
                  gap={4}
                >
                  <Text size={TextSize.small}>{reaction.displayKey}</Text>
                  <Text
                    size={TextSize.small}
                    color={isActive ? Colors.white : Colors.white50}
                    font="InstrumentSans-Bold"
                  >
                    {reaction.count}
                  </Text>
                </Block>
              );
            })}
          </ScrollView>
        </Block>

        <Block paddings={{ paddingHorizontal: 20, paddingBottom: 56 }}>
          {activeReaction?.senders?.map(({ userId, timestamp }) => (
            <ReactionUserRow
              key={userId}
              userId={userId}
              timestamp={timestamp}
            />
          ))}
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

import { BottomSheetScrollView } from "@gorhom/bottom-sheet";
import { Block, Text } from "@prototyp/skeletor";
import {
  type EventTimelineItem,
  type ImageMessageContent,
  MessageType_Tags,
  MsgLikeKind_Tags,
  ProfileDetails_Tags,
  TimelineItemContent_Tags,
} from "@unomed/react-native-matrix-sdk";
import { format } from "date-fns";
import { useAtom, useSetAtom } from "jotai";
import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
import { getEventId } from "modules/matrix-client/utils";
import { NavigationContainerRef } from "modules/navigation/const";
import { TimelineAtoms } from "modules/timeline/jotai";
import { TimelineService } from "modules/timeline/service/TimelineService";
import { type FC, useCallback, useMemo, useRef, useState } from "react";
import { Alert, Dimensions, Share } from "react-native";
import { Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { UserImage } from "shared/components/user-image/UserImage";
import { Colors } from "shared/styles";
import { formatBytes, offlineToastHelper } from "shared/utils";
import { InfoRow } from "../info-row";
import { MessageContentListItem } from "../message-content-item-list";

const getImageContent = (
  event: EventTimelineItem,
): ImageMessageContent | null => {
  if (event.content.tag === TimelineItemContent_Tags.MsgLike) {
    const kind = event.content.inner.content.kind;
    if (kind?.tag === MsgLikeKind_Tags.Message) {
      const msgType = kind.inner.content.msgType;
      if (msgType?.tag === MessageType_Tags.Image) {
        return msgType.inner.content;
      }
    }
  }
  return null;
};

const { height: SCREEN_HEIGHT } = Dimensions.get("window");

export const ImageInfoBottomSheet: FC = () => {
  const sheetRef = useRef<AppBottomSheetRef>(null);
  const [payload, setPayload] = useAtom(TimelineAtoms.imageInfoPayload);
  const [preparingAction, setPreparingAction] = useState<
    "share" | "download" | null
  >(null);
  const event = payload?.event ?? null;
  const roomId = payload?.roomId ?? null;
  const localUri = payload?.localUri ?? null;
  const imageContent = useMemo(
    () => (event ? getImageContent(event) : null),
    [event],
  );
  const avatarUrl =
    event?.senderProfile.tag === ProfileDetails_Tags.Ready
      ? event.senderProfile.inner.avatarUrl
      : null;
  const displayName =
    event?.senderProfile.tag === ProfileDetails_Tags.Ready
      ? event.senderProfile.inner.displayName
      : undefined;
  const senderName = displayName ?? event?.sender ?? "";
  const formattedDate = useMemo(
    () => (event ? format(Number(event.timestamp), "MMM d, yyyy HH:mm") : ""),
    [event],
  );
  const filename = imageContent?.filename ?? "Image";
  const mimetype = imageContent?.info?.mimetype ?? "image/*";
  const size = formatBytes(imageContent?.info?.size);
  const isOwn = !!event?.isOwn;
  const setMediaViewerPayload = useSetAtom(TimelineAtoms.mediaViewerPayload);
  const setReplyPayload = useSetAtom(TimelineAtoms.replyPayload);
  const setEditPayload = useSetAtom(TimelineAtoms.editPayload);
  const setForwardPayload = useSetAtom(TimelineAtoms.forwardPayload);
  const closeSheet = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleClose = useCallback(() => {
    setPayload(null);
  }, [setPayload]);

  const handleReply = useCallback(() => {
    if (!event || !imageContent) {
      closeSheet();
      return;
    }
    const eventId = getEventId(event);
    if (!eventId) {
      closeSheet();
      return;
    }

    setEditPayload(null);
    setReplyPayload({
      eventId,
      senderName,
      content: imageContent.caption ?? filename,
      mediaSource: {
        source: imageContent.source,
        mimetype,
      },
    });
    closeSheet();
    setMediaViewerPayload(null);
  }, [
    event,
    imageContent,
    senderName,
    filename,
    mimetype,
    setEditPayload,
    setReplyPayload,
    setMediaViewerPayload,
    closeSheet,
  ]);

  const handleForward = useCallback(() => {
    if (!event || !roomId) return;

    setForwardPayload({
      event,
      content: imageContent?.caption ?? filename,
      messageType: "image",
    });
    closeSheet();
    setMediaViewerPayload(null);
    NavigationContainerRef.navigate("forwardMessage", {
      currentRoomId: roomId,
    });
  }, [
    event,
    roomId,
    imageContent,
    filename,
    setForwardPayload,
    setMediaViewerPayload,
    closeSheet,
  ]);

  const shareNamedFile = useCallback(async () => {
    if (!imageContent || !MatrixCore.instance) {
      if (!localUri) {
        offlineToastHelper("Image not ready yet");
        return;
      }
      const fallbackUrl = localUri.startsWith("file://")
        ? localUri
        : `file://${localUri}`;
      await Share.share({ url: fallbackUrl });
      return;
    }
    const mediaHandle = await MatrixCore.instance.getMediaFile(
      imageContent.source,
      filename,
      mimetype,
      false,
      undefined,
    );
    const filePath = mediaHandle.path();
    const url = filePath.startsWith("file://")
      ? filePath
      : `file://${filePath}`;
    await Share.share({ url });
  }, [imageContent, filename, mimetype, localUri]);

  const handleShare = useCallback(async () => {
    setPreparingAction("share");
    try {
      await shareNamedFile();
    } catch {
      offlineToastHelper("Failed to share image");
    } finally {
      setPreparingAction(null);
      closeSheet();
    }
  }, [shareNamedFile, closeSheet]);

  const handleDownload = useCallback(async () => {
    setPreparingAction("download");
    try {
      await shareNamedFile();
    } catch {
      offlineToastHelper("Failed to download image");
    } finally {
      setPreparingAction(null);
      closeSheet();
    }
  }, [shareNamedFile, closeSheet]);

  const handleDelete = useCallback(() => {
    if (!event || !roomId) return;
    Alert.alert(
      "Delete message",
      "Are you sure you want to delete this image? This cannot be undone.",
      [
        { text: "Cancel", style: "cancel" },
        {
          text: "Delete",
          style: "destructive",
          onPress: async () => {
            try {
              await TimelineService.deleteMessage(roomId, event);
              closeSheet();
              setMediaViewerPayload(null);
            } catch (error) {
              console.error("Failed to delete message:", error);
              offlineToastHelper("Failed to delete message");
            }
          },
        },
      ],
    );
  }, [event, roomId, setMediaViewerPayload, closeSheet]);

  return (
    <AppBottomSheet
      ref={sheetRef}
      isOpen={!!payload}
      onClose={handleClose}
      enableContentPanningGesture={false}
      maxContentSize={SCREEN_HEIGHT - 100}
      hideBackdrop
    >
      <BottomSheetScrollView scrollEnabled={false}>
        <Block paddings={{ paddingHorizontal: 20, paddingBottom: 40 }} gap={20}>
          {preparingAction && (
            <Block
              absolute
              offsets={[0, 0, 0, 0]}
              background={Colors.black70}
              zIndex={1}
            >
              <Loading
                isFullScreen={false}
                text={
                  preparingAction === "download"
                    ? "Preparing download..."
                    : "Preparing share..."
                }
              />
            </Block>
          )}
          <Block flexDirection="row" gap={12} align="center">
            <UserImage
              avatarUrl={avatarUrl}
              displayName={displayName}
              width={48}
              height={48}
              borderRadius={999}
            />
            <Block flex={1} gap={2}>
              <Text
                color={Colors.white}
                font="InstrumentSans-Semibold"
                numberOfLines={1}
              >
                {senderName}
              </Text>
              <Text color={Colors.white50} numberOfLines={1}>
                {event?.sender}
              </Text>
            </Block>
          </Block>

          <Block
            border={{ borderBottomWidth: 1, borderColor: Colors.white5 }}
            paddings={{ paddingBottom: 20 }}
          >
            <InfoRow label="Date" value={formattedDate} />
            <InfoRow label="Name" value={filename} />
            <InfoRow label="Type" value={mimetype} />
            <InfoRow label="Size" value={size} isLast />
          </Block>

          <Block>
            <MessageContentListItem
              title="Reply"
              icon={require("assets/icons/reply.png")}
              onPress={handleReply}
            />
            <MessageContentListItem
              title="Forward"
              icon={require("assets/icons/forward.png")}
              onPress={handleForward}
            />
            <MessageContentListItem
              title="Share"
              icon={require("assets/icons/upload-simple-large.png")}
              onPress={handleShare}
            />
            <MessageContentListItem
              title="Download"
              icon={require("assets/icons/download.png")}
              onPress={handleDownload}
              hasSeparator={isOwn}
            />
            {isOwn && (
              <MessageContentListItem
                title="Delete message"
                icon={require("assets/icons/trash.png")}
                onPress={handleDelete}
                tintColor={Colors.error}
                textColor={Colors.error}
                hasSeparator={false}
              />
            )}
          </Block>
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

import {
  BottomSheetScrollView,
  BottomSheetTextInput,
} from "@gorhom/bottom-sheet";
import { Block, Text, useAndroidBackHandler } from "@prototyp/skeletor";
import { resetToRoom } from "modules/navigation/utils";
import { RoomService } from "modules/room/service/RoomService";
import { type FC, useCallback, useRef, useState } from "react";
import { Button, Input, Loading } from "shared/components";
import {
  AppBottomSheet,
  type AppBottomSheetRef,
} from "shared/components/bottom-sheet";
import { Colors, TextSize } from "shared/styles";
import { offlineToastHelper } from "shared/utils";

interface Props {
  isBottomSheetOpen: boolean;
  setIsBottomSheetOpen: (value: boolean) => void;
}

const ROOM_ADDRESS_REGEX = /^#.+:.+$/;

export const JoinRoom: FC<Props> = ({
  isBottomSheetOpen,
  setIsBottomSheetOpen,
}) => {
  const [roomAddress, setRoomAddress] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const sheetRef = useRef<AppBottomSheetRef>(null);

  const handleTextChange = (text: string) => {
    setRoomAddress(text);
    setError(null);
  };

  const handleClose = useCallback(() => {
    setIsBottomSheetOpen(false);
    setRoomAddress("");
    setError(null);
  }, [setIsBottomSheetOpen]);

  const handleCloseOnPress = useCallback(() => {
    sheetRef.current?.close();
  }, []);

  const handleJoinRoom = useCallback(async () => {
    const trimmedAddress = roomAddress.trim();

    if (!trimmedAddress) {
      setError("Please enter a room address.");
      return;
    }

    if (!ROOM_ADDRESS_REGEX.test(trimmedAddress)) {
      setError("Enter a valid room address.");
      return;
    }

    setLoading(true);
    setError(null);

    try {
      const roomId = await RoomService.joinRoomByAddress(trimmedAddress);

      resetToRoom(roomId);

      sheetRef.current?.close();
    } catch (err) {
      offlineToastHelper("Failed to join room");
      console.error("Failed to join room:", err);
    } finally {
      setLoading(false);
    }
  }, [roomAddress]);

  useAndroidBackHandler({
    handlePress: handleCloseOnPress,
    enabled: isBottomSheetOpen,
    disableDefault: isBottomSheetOpen,
  });

  return (
    <AppBottomSheet
      ref={sheetRef}
      isOpen={isBottomSheetOpen}
      enableContentPanningGesture={false}
      keyboardBehavior="interactive"
      keyboardBlurBehavior="restore"
      android_keyboardInputMode="adjustResize"
      onClose={handleClose}
    >
      <BottomSheetScrollView scrollEnabled={false}>
        <Block
          justify="space-between"
          flexDirection="column"
          flex={1}
          width="100%"
          gap={8}
          paddings={{
            paddingHorizontal: 12,
            paddingBottom: 36,
          }}
        >
          <Text
            size={TextSize.small}
            color={Colors.white}
            font="InstrumentSans-Bold"
            paddings={{ paddingHorizontal: 14 }}
          >
            Join room by address
          </Text>
          <Input
            placeholder="Enter room address"
            background={Colors.white5}
            value={roomAddress}
            onChangeText={handleTextChange}
            autoCapitalize="none"
            editable={!loading}
            InputComponent={BottomSheetTextInput}
          />

          {error ? (
            <Text
              size={TextSize.tiny}
              color="red"
              font="InstrumentSans-Regular"
              paddings={{ paddingHorizontal: 14 }}
              margins={{ marginBottom: 8 }}
            >
              {error}
            </Text>
          ) : (
            <Text
              size={TextSize.tiny}
              color={Colors.white50}
              font="InstrumentSans-Regular"
              paddings={{ paddingHorizontal: 14 }}
              margins={{ marginBottom: 8 }}
            >
              e.g. #room-name:matrix.org
            </Text>
          )}
          <Button.Primary onPress={handleJoinRoom} disabled={loading}>
            {loading ? "Joining..." : "Join room"}
          </Button.Primary>
          {loading && <Loading text="Joining room..." />}
        </Block>
      </BottomSheetScrollView>
    </AppBottomSheet>
  );
};

